def fibonacci(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def is_palindrome(s: str) -> bool:
    t = ''.join(c.lower() for c in s if c.isalnum())
    return t == t[::-1]

def remove_duplicates(lst: list) -> list:
    out = []
    for x in lst:
        if x not in out:
            out.append(x)
    return out

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def factorial(n: int) -> int:
    r = 1
    for i in range(2, n + 1):
        r *= i
    return r

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return abs(a)

def flatten_once(lst: list) -> list:
    out = []
    for x in lst:
        out.extend(x)
    return out

def intersection(a: list, b: list) -> list:
    seen = set()
    out = []
    for x in a:
        if x in b and x not in seen:
            seen.add(x)
            out.append(x)
    return out

def is_anagram(s1: str, s2: str) -> bool:
    f = lambda s: sorted(c.lower() for c in s if c.isalnum())
    return f(s1) == f(s2)

def longest_word(s: str) -> str:
    ws = s.split()
    if not ws:
        return ''
    best = ws[0]
    for w in ws[1:]:
        if len(w) > len(best):
            best = w
    return best

def multiply_all(lst: list) -> int:
    r = 1
    for x in lst:
        r *= x
    return r

def is_perfect_square(n: int) -> bool:
    if n < 0:
        return False
    r = int(n ** 0.5)
    return r * r == n or (r+1) * (r+1) == n

def rotate_left(lst: list, k: int) -> list:
    if not lst:
        return []
    k %= len(lst)
    return lst[k:] + lst[:k]

def first_unique(s: str) -> str:
    for c in s:
        if s.count(c) == 1:
            return c
    return ''

def max_sum_subarray(arr):
    best = cur = arr[0]
    for x in arr[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best

def merge_intervals(intervals):
    if not intervals:
        return []
    s = sorted(intervals)
    out = [list(s[0])]
    for a, b in s[1:]:
        if a <= out[-1][1]:
            out[-1][1] = max(out[-1][1], b)
        else:
            out.append([a, b])
    return [tuple(x) for x in out]
